/**
 * SHIVI AI — PPT DECK MONGOOSE MODEL
 * 
 * Stores presentation deck metadata, slide structures, themes,
 * and download paths generated by Shivi AI Keynote Studio.
 */

const mongoose = require('mongoose');

const PptDeckSchema = new mongoose.Schema({
    id: {
        type: String,
        default: () => 'deck_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 7),
        unique: true,
        index: true
    },
    userId: {
        type: String,
        default: 'guest',
        index: true
    },
    userEmail: {
        type: String,
        default: '',
        index: true
    },
    sessionId: {
        type: String,
        default: '',
        index: true
    },
    title: {
        type: String,
        required: true,
        trim: true
    },
    topic: {
        type: String,
        required: true,
        trim: true
    },
    theme: {
        type: String,
        default: 'modern_blue'
    },
    slideCount: {
        type: Number,
        default: 0
    },
    filename: {
        type: String,
        default: () => 'presentation_' + Date.now() + '.pptx'
    },
    downloadUrl: {
        type: String,
        default: () => '/api/presentation/download/presentation_' + Date.now() + '.pptx'
    },
    filePath: {
        type: String,
        default: ''
    },
    slides: {
        type: [mongoose.Schema.Types.Mixed],
        default: []
    },
    deckData: {
        type: mongoose.Schema.Types.Mixed,
        default: null
    }
}, {
    timestamps: true,
    collection: 'ppt_decks'
});

PptDeckSchema.index({ userId: 1, createdAt: -1 });
PptDeckSchema.index({ userEmail: 1, createdAt: -1 });

const PptDeck = mongoose.models.PptDeck || mongoose.model('PptDeck', PptDeckSchema);

module.exports = PptDeck;
